package dustin.cex.domains.bitcoin;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.awaitility.Awaitility.await;
import dustin.cex.domains.monitoring.DepositMonitoringService;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.env.MapPropertySource;

/** 실제 전용 실행기의 비중첩·고정 지연·실패 회복·종료/프로필 경계를 확인한다. DB·노드 호출은 하지 않는다. */
class BitcoinDepositMonitoringWorkerTest {
    BitcoinSettings configured(){return new BitcoinSettings("http://127.0.0.1:1","isolated","isolated-worker-password-at-least-32-bytes","cex_watch","REGTEST");}
    @Test void disabledOrUnconfiguredDoesNotPoll(){var service=mock(DepositMonitoringService.class);for(var worker:List.of(new BitcoinDepositMonitoringWorker(configured(),service,false),new BitcoinDepositMonitoringWorker(new BitcoinSettings("","","","","REGTEST"),service,true))){worker.start();worker.stop();}verifyNoInteractions(service);}
    @Test void oneDedicatedThreadCannotOverlapOrCreateDuplicateExecutors()throws Exception{var service=mock(DepositMonitoringService.class);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new AtomicInteger();var thread=new AtomicReference<String>();when(service.processNext()).thenAnswer(call->{calls.incrementAndGet();thread.set(Thread.currentThread().getName());entered.countDown();release.await();return Optional.empty();});var worker=new BitcoinDepositMonitoringWorker(configured(),service,true);try{worker.start();worker.start();assertTrue(entered.await(3,TimeUnit.SECONDS));await().during(Duration.ofMillis(100)).atMost(Duration.ofSeconds(1)).until(()->calls.get()==1);assertTrue(thread.get().startsWith("bitcoin-deposit-monitoring-"));}finally{release.countDown();worker.stop();}}
    @Test void delayBeginsAfterPreviousWorkCompletes()throws Exception{var service=mock(DepositMonitoringService.class);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new AtomicInteger();var finished=new AtomicLong();var second=new AtomicLong();when(service.processNext()).thenAnswer(call->{int n=calls.incrementAndGet();if(n==1){entered.countDown();assertTrue(release.await(10,TimeUnit.SECONDS));finished.set(System.nanoTime());}else if(n==2)second.set(System.nanoTime());return Optional.empty();});var worker=new BitcoinDepositMonitoringWorker(configured(),service,true);try{worker.start();assertTrue(entered.await(3,TimeUnit.SECONDS));Thread.sleep(1100);assertEquals(1,calls.get());release.countDown();await().atMost(Duration.ofSeconds(4)).until(()->second.get()!=0);assertNotEquals(0,finished.get());assertTrue(second.get()-finished.get()>=TimeUnit.SECONDS.toNanos(1));}finally{release.countDown();worker.stop();}}
    @Test void failureDoesNotCancelLaterPolling(){var service=mock(DepositMonitoringService.class);var calls=new AtomicInteger();when(service.processNext()).thenAnswer(call->{if(calls.incrementAndGet()==1)throw new IllegalStateException("격리 민감 원문");return Optional.empty();});var worker=new BitcoinDepositMonitoringWorker(configured(),service,true);try{worker.start();await().atMost(Duration.ofSeconds(4)).until(()->calls.get()>=2);}finally{worker.stop();}}
    @Test void terminatedWorkerCanRestart(){var service=mock(DepositMonitoringService.class);var calls=new AtomicInteger();when(service.processNext()).thenAnswer(call->{calls.incrementAndGet();return Optional.empty();});var worker=new BitcoinDepositMonitoringWorker(configured(),service,true);try{worker.start();await().atMost(Duration.ofSeconds(3)).until(()->calls.get()>=1);worker.stop();int before=calls.get();worker.start();await().atMost(Duration.ofSeconds(3)).until(()->calls.get()>before);}finally{worker.stop();}}
    @Test void ignoredShutdownCannotStartOverlappingReplacement()throws Exception{var service=mock(DepositMonitoringService.class);var calls=new AtomicInteger();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);when(service.processNext()).thenAnswer(call->{calls.incrementAndGet();entered.countDown();while(release.getCount()>0){try{release.await();}catch(InterruptedException ignored){}}return Optional.empty();});var worker=new BitcoinDepositMonitoringWorker(configured(),service,true);try{worker.start();assertTrue(entered.await(3,TimeUnit.SECONDS));worker.stop();worker.start();await().during(Duration.ofMillis(100)).atMost(Duration.ofSeconds(1)).until(()->calls.get()==1);}finally{release.countDown();worker.stop();}}
    AnnotationConfigApplicationContext context(String profile,boolean enabled,DepositMonitoringService service){var ctx=new AnnotationConfigApplicationContext();ctx.getEnvironment().setActiveProfiles(profile);ctx.getEnvironment().getPropertySources().addFirst(new MapPropertySource("격리 모니터링 설정",Map.of("bitcoin.processing.enabled",Boolean.toString(enabled))));ctx.registerBean("depositMonitoringSchemaInitializer",Object.class,Object::new);ctx.registerBean(BitcoinSettings.class,this::configured);ctx.registerBean(DepositMonitoringService.class,()->service);ctx.register(BitcoinDepositMonitoringWorker.class);ctx.refresh();return ctx;}
    @Test void testProfileNeverStartsAutomaticMonitoring(){var service=mock(DepositMonitoringService.class);try(var ctx=context("test",true,service)){assertTrue(ctx.getBeansOfType(BitcoinDepositMonitoringWorker.class).isEmpty());verifyNoInteractions(service);}}
    @Test void productionHonorsFlagAndClosesItsExecutor(){var service=mock(DepositMonitoringService.class);when(service.processNext()).thenReturn(Optional.empty());try(var ctx=context("production",false,service)){assertEquals(1,ctx.getBeansOfType(BitcoinDepositMonitoringWorker.class).size());verifyNoInteractions(service);}try(var ctx=context("production",true,service)){await().atMost(Duration.ofSeconds(3)).untilAsserted(()->verify(service,atLeastOnce()).processNext());}await().atMost(Duration.ofSeconds(2)).until(()->Thread.getAllStackTraces().keySet().stream().noneMatch(t->t.isAlive()&&t.getName().startsWith("bitcoin-deposit-monitoring-")));}
    @Test void emptyPollingAfterFailureDoesNotClaimRecoveryBeforeACompletedJob(){
        var service=mock(DepositMonitoringService.class);var calls=new AtomicInteger();when(service.processNext()).thenAnswer(call->{if(calls.incrementAndGet()==1)throw new IllegalStateException("격리 민감 원문");return Optional.empty();});
        var events=new CopyOnWriteArrayList<String>();var logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(BitcoinDepositMonitoringWorker.class);
        var sink=new ch.qos.logback.core.AppenderBase<ch.qos.logback.classic.spi.ILoggingEvent>(){protected void append(ch.qos.logback.classic.spi.ILoggingEvent event){events.add(event.getFormattedMessage());}};sink.setContext(logger.getLoggerContext());sink.start();logger.addAppender(sink);
        var worker=new BitcoinDepositMonitoringWorker(configured(),service,true);
        try{worker.start();await().atMost(Duration.ofSeconds(4)).until(()->calls.get()>=2);assertTrue(events.stream().noneMatch(x->x.contains("처리 재개")));assertTrue(events.stream().noneMatch(x->x.contains("격리 민감 원문")));doReturn(Optional.of(mock(DepositMonitoringService.Assessment.class))).when(service).processNext();await().atMost(Duration.ofSeconds(4)).until(()->events.stream().anyMatch(x->x.contains("처리 재개")));}
        finally{worker.stop();logger.detachAppender(sink);sink.stop();}
    }
}
